const before = wb.getRange("'Sheet1'!A1:BIG5").getValues();
const toLetter = (i)=>{let s='';i++;while(i>0){const m=(i-1)%26;s=String.fromCharCode(65+m)+s;i=(i-m-1)/26;}return s;};
const hdr = before[0];
const del = hdr.map((v,i)=>String(v??'').includes('/description')?i:-1).filter(i=>i>=0);
for (let k=del.length-1;k>=0;k--){ const c=toLetter(del[k]); wb.getRange(`'Sheet1'!${c}:${c}`).delete(); }
const after = wb.getRange("'Sheet1'!A1:BIG5").getValues();
const keep = hdr.map((_,i)=>i).filter(i=>!del.includes(i));
let mism=0;
for(let r=0;r<5;r++){ keep.forEach((i,j)=>{ const a=before[r][i]??null, b=after[r][j]??null; if(a!==b) mism++; }); for(let j=keep.length;j<hdr.length;j++){ if((after[r][j]??null)!==null && after[r][j]!=='') mism++; } }
const stillHit = after[0].filter(v=>String(v??'').includes('/description')).length;
log(JSON.stringify({deleted:del.length, kept:keep.length, mism, stillHit, used:wb.getWorksheet('Sheet1').getUsedRange().getA1?.(), head:after[0].slice(0,6), lastKept:after[0].slice(keep.length-3,keep.length+1)}));
wb.getRange("'Sheet1'!A1:F5")

